&lt;li&gt;
&lt;p data-path-to-node=&quot;10,10,0&quot;&gt;&lt;span data-path-to-node=&quot;10,10,0,1&quot;&gt;&lt;span class=&quot;citation-2826&quot;&gt;Project management experience for projects affecting multiple teams&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
