&lt;p data-path-to-node=&quot;10,11,0&quot;&gt;&lt;span data-path-to-node=&quot;10,11,0,1&quot;&gt;&lt;span class=&quot;citation-2825&quot;&gt;Experience working within an Agile environment with a strong customer focus&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
